UPDATED_FILES = {'README.md': '# Plataforma de Serviços Mecânicos\n\nProjeto independente para conectar clientes e fornecedores de serviços mecânicos.\n\n## Regra de idioma\n\nA aplicação é desenvolvida em português: interface, documentação, mensagens,\nvalidações, nomes do domínio e módulos específicos da aplicação.\n\nNomes de tecnologias externas, como Python, FastAPI, SQLAlchemy, SQLite e Uvicorn,\npermanecem com seus nomes oficiais.\n\n## Estado\n\n**V0.1 D4 — Capacidade Técnica do Fornecedor**\n\nNesta etapa foram estruturados:\n\n- catálogo de processos de fabricação;\n- catálogo de materiais;\n- capacidades técnicas por fornecedor e processo;\n- máquinas por fornecedor e processo;\n- materiais aceitos por fornecedor;\n- dimensões máximas em milímetros;\n- tolerância mínima em milímetros.\n\nO projeto continua independente do CGX Platform.\n\n## Executar\n\n```powershell\npython -m pytest\npython -m uvicorn backend.app.principal:app --reload\n```\n\n## Endpoints principais\n\n- `http://127.0.0.1:8000/`\n- `http://127.0.0.1:8000/api/v1/saude`\n- `http://127.0.0.1:8000/api/v1/banco-dados/saude`\n- `http://127.0.0.1:8000/api/v1/empresas`\n- `http://127.0.0.1:8000/api/v1/processos-fabricacao`\n- `http://127.0.0.1:8000/api/v1/materiais`\n- `http://127.0.0.1:8000/docs`\n', 'backend/app/models/__init__.py': 'from backend.app.models.empresa import Empresa\nfrom backend.app.models.processo import ProcessoFabricacao\nfrom backend.app.models.material import Material\nfrom backend.app.models.capacidade import CapacidadeFornecedor\nfrom backend.app.models.maquina import Maquina\nfrom backend.app.models.material_fornecedor import MaterialFornecedor\n\n__all__ = [\n    "Empresa", "ProcessoFabricacao", "Material",\n    "CapacidadeFornecedor", "Maquina", "MaterialFornecedor",\n]\n', 'backend/app/database/inicializacao.py': 'from __future__ import annotations\n\nfrom pathlib import Path\nfrom sqlalchemy import inspect, text\nfrom backend.app.core.configuracao import configuracoes\nfrom backend.app.database.base import Base\nfrom backend.app.database.sessao import engine\nfrom backend.app.models import (\n    CapacidadeFornecedor, Empresa, Maquina, Material,\n    MaterialFornecedor, ProcessoFabricacao,\n)\n\n\ndef _garantir_pasta_sqlite() -> None:\n    prefixo = "sqlite:///"\n    if not configuracoes.url_banco_dados.startswith(prefixo):\n        return\n    caminho_bruto = configuracoes.url_banco_dados[len(prefixo):]\n    if not caminho_bruto or caminho_bruto == ":memory:":\n        return\n    caminho = Path(caminho_bruto)\n    if not caminho.is_absolute():\n        caminho = Path.cwd() / caminho\n    caminho.parent.mkdir(parents=True, exist_ok=True)\n\n\ndef _migrar_companies_para_empresas() -> None:\n    if not configuracoes.url_banco_dados.startswith("sqlite"):\n        return\n    inspetor = inspect(engine)\n    tabelas = set(inspetor.get_table_names())\n    if "empresas" in tabelas and "companies" in tabelas:\n        raise RuntimeError("Banco em estado ambíguo: as tabelas \'companies\' e \'empresas\' existem simultaneamente.")\n    if "companies" not in tabelas:\n        return\n    colunas = {coluna["name"] for coluna in inspetor.get_columns("companies")}\n    esperadas = {"id", "legal_name", "document", "company_type", "rating", "created_at", "updated_at"}\n    ausentes = esperadas - colunas\n    if ausentes:\n        raise RuntimeError("A tabela legada \'companies\' não possui as colunas esperadas: " + ", ".join(sorted(ausentes)))\n    with engine.begin() as conexao:\n        tipos_invalidos = conexao.execute(text("""\n            SELECT DISTINCT company_type FROM companies\n            WHERE company_type NOT IN (\'client\', \'supplier\', \'both\')\n        """)).scalars().all()\n        if tipos_invalidos:\n            raise RuntimeError("A tabela legada \'companies\' possui tipos de empresa desconhecidos: " + ", ".join(str(valor) for valor in tipos_invalidos))\n        conexao.execute(text("""\n            CREATE TABLE empresas (\n                id INTEGER PRIMARY KEY,\n                razao_social VARCHAR(200) NOT NULL,\n                documento VARCHAR(32) NOT NULL UNIQUE,\n                tipo_empresa VARCHAR(16) NOT NULL CHECK (tipo_empresa IN (\'cliente\', \'fornecedor\', \'ambos\')),\n                avaliacao FLOAT,\n                criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                CONSTRAINT ck_empresas_avaliacao CHECK (avaliacao IS NULL OR (avaliacao >= 0 AND avaliacao <= 5))\n            )\n        """))\n        conexao.execute(text("""\n            INSERT INTO empresas (id, razao_social, documento, tipo_empresa, avaliacao, criado_em, atualizado_em)\n            SELECT id, legal_name, document,\n                CASE company_type WHEN \'client\' THEN \'cliente\' WHEN \'supplier\' THEN \'fornecedor\' WHEN \'both\' THEN \'ambos\' END,\n                rating, created_at, updated_at\n            FROM companies\n        """))\n        conexao.execute(text("CREATE INDEX IF NOT EXISTS ix_empresas_razao_social ON empresas (razao_social)"))\n        conexao.execute(text("DROP TABLE companies"))\n\n\ndef inicializar_banco() -> None:\n    _garantir_pasta_sqlite()\n    _migrar_companies_para_empresas()\n    Base.metadata.create_all(bind=engine)\n', 'backend/app/api/roteador.py': 'from __future__ import annotations\nfrom fastapi import APIRouter\nfrom backend.app.api.rotas.banco_dados import roteador as roteador_banco\nfrom backend.app.api.rotas.empresas import roteador as roteador_empresas\nfrom backend.app.api.rotas.saude import roteador as roteador_saude\nfrom backend.app.api.rotas.processos import roteador as roteador_processos\nfrom backend.app.api.rotas.materiais import roteador as roteador_materiais\nfrom backend.app.api.rotas.capacidades import roteador as roteador_capacidades\n\nroteador_api = APIRouter()\nroteador_api.include_router(roteador_saude)\nroteador_api.include_router(roteador_banco)\nroteador_api.include_router(roteador_empresas)\nroteador_api.include_router(roteador_processos)\nroteador_api.include_router(roteador_materiais)\nroteador_api.include_router(roteador_capacidades)\n', 'backend/app/repositories/__init__.py': 'from backend.app.repositories.empresa import RepositorioEmpresa\nfrom backend.app.repositories.capacidade import RepositorioCapacidade\n\n__all__ = ["RepositorioEmpresa", "RepositorioCapacidade"]\n', 'backend/app/schemas/__init__.py': 'from backend.app.schemas.empresa import EmpresaCriacao, EmpresaLeitura, TipoEmpresa\nfrom backend.app.schemas.processo import ProcessoCriacao, ProcessoLeitura\nfrom backend.app.schemas.material import MaterialCriacao, MaterialLeitura\nfrom backend.app.schemas.capacidade import (\n    CapacidadeCriacao, CapacidadeLeitura, MaquinaCriacao, MaquinaLeitura,\n    MaterialFornecedorCriacao, MaterialFornecedorLeitura,\n)\n\n__all__ = [\n    "EmpresaCriacao", "EmpresaLeitura", "TipoEmpresa",\n    "ProcessoCriacao", "ProcessoLeitura", "MaterialCriacao", "MaterialLeitura",\n    "CapacidadeCriacao", "CapacidadeLeitura", "MaquinaCriacao", "MaquinaLeitura",\n    "MaterialFornecedorCriacao", "MaterialFornecedorLeitura",\n]\n'}
